import random
def reset_token(r):
    return ''.join(r.choice('0123456789abcdef') for _ in range(8))
known=open('token.txt').read().strip()
lo,hi=[int(x) for x in open('window.txt').read().split()]
for s in range(lo,hi):
    r=random.Random(s)
    if reset_token(r)==known:
        nxt=reset_token(r)
        print('seed      :', s)
        print('known     :', known)
        print('next token: nto{'+nxt+'}')
        break
